SELECT block_number,block_time,hex(block_hash) AS block_hash_hex,hex(payload_hash) AS payload_hash_hex,quote_role,route_id,quote_mode,hex(token_in) AS token_in_hex,hex(token_out) AS token_out_hex,toString(requested_amount_raw) AS requested_atoms,toString(amount_in_raw) AS input_atoms,toString(amount_out_raw) AS output_atoms,status,reason FROM dex_route_quote FINAL WHERE chain_id=1 AND manifest_hash=unhex('e5493d29bf16f2d7665e90163eda323e2e7a2847e4bd3e7563db77ac11bfe567') AND block_number=26098873 AND block_hash=unhex('F47925358BB6F2017D6F5753D8A492B6088E2D55BBD5B992AC641296200A8DB1') AND batch_id=unhex('308F4ACD1F441BF153E98EB43004E26921FF7AB43BE69A5DD1ED769FD46A7470') AND (quote_role='cost' OR requested_amount_raw=1000000000000) ORDER BY quote_role,route_id FORMAT JSONEachRow
